  h: 150,
  box: { x0: 198, y0: 160, x1: 810, y1: 828 },
  clips: {
    worried: { frames: 8, fps: 8 },
    wave: { frames: 7, fps: 8 },
    shy: { frames: 9, fps: 8 },
  },
  peek: {
